<script setup>
import { ref } from 'vue'; import { Head, useForm } from '@inertiajs/vue3'; import AuthenticatedLayout from '@/Layouts/AuthenticatedLayout.vue';
const props = defineProps({ events: { type: Array, default: () => [] }, notes: { type: Array, default: () => [] } }); const editing = ref(null);
const form = useForm({ title: '', description: '', starts_at: '', ends_at: '', all_day: false, color: '#6366f1', location: '', note_id: '' });
function reset() { editing.value = null; form.reset(); form.color = '#6366f1'; } function edit(event) { editing.value = event.id; Object.assign(form, { title: event.title, description: event.description || '', starts_at: event.starts_at?.slice(0,16) || '', ends_at: event.ends_at?.slice(0,16) || '', all_day: event.all_day, color: event.color, location: event.location || '', note_id: event.note_id || '' }); } function save() { const options = { preserveScroll: true, onSuccess: reset }; editing.value ? form.put(route('calendar.update', editing.value), options) : form.post(route('calendar.store'), options); } function remove(event) { if (confirm('Remover este evento?')) useForm({}).delete(route('calendar.destroy', event.id)); }
</script>
<template><Head title="Agenda" /><AuthenticatedLayout><div class="max-w-6xl"><div class="flex flex-col gap-4 border-b border-slate-200 pb-6 sm:flex-row sm:items-center sm:justify-between"><div><nav class="mb-1 flex items-center gap-2 text-xs font-medium uppercase tracking-wider text-slate-400"><span>Geral</span><span>/</span><span class="text-slate-600">Agenda</span></nav><h1 class="text-2xl font-bold tracking-tight text-slate-900">Minha Agenda</h1><p class="mt-1 text-sm text-slate-500">Organize compromissos e conecte anotações.</p></div><button @click="reset" class="inline-flex items-center justify-center gap-2 rounded-xl bg-slate-900 px-4 py-2.5 text-sm font-medium text-white shadow-sm transition hover:bg-slate-800"><svg class="h-4 w-4" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><line x1="12" y1="5" x2="12" y2="19"/><line x1="5" y1="12" x2="19" y2="12"/></svg>Novo evento</button></div><div class="mt-8 grid gap-6 lg:grid-cols-[minmax(0,1fr)_360px]"><section class="space-y-4"><div v-if="!events.length" class="rounded-2xl border border-dashed border-slate-300 bg-white p-12 text-center text-sm text-slate-500">Sua agenda está livre. Adicione um evento para começar.</div><article v-for="event in events" :key="event.id" class="flex gap-4 rounded-2xl border border-slate-200 bg-white p-5 shadow-sm"><div class="mt-1 h-10 w-1.5 shrink-0 rounded-full" :style="{ backgroundColor: event.color }"></div><div class="min-w-0 flex-1"><div class="flex items-start justify-between gap-3"><div><h2 class="font-semibold text-slate-900">{{ event.title }}</h2><p class="mt-1 text-sm text-indigo-700">{{ new Date(event.starts_at).toLocaleString('pt-BR', { dateStyle: 'short', timeStyle: 'short' }) }}</p></div><div class="flex items-center gap-1"><button @click="edit(event)" class="rounded-lg p-1.5 text-slate-400 transition hover:bg-slate-100 hover:text-slate-700" title="Editar evento"><svg class="h-4 w-4" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M12 20h9"/><path d="M16.5 3.5a2.1 2.1 0 0 1 3 3L8 18l-4 1 1-4Z"/></svg></button><button @click="remove(event)" class="rounded-lg p-1.5 text-slate-400 transition hover:bg-rose-50 hover:text-rose-600" title="Remover evento"><svg class="h-4 w-4" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><polyline points="3 6 5 6 21 6"/><path d="M19 6v14a2 2 0 0 1-2 2H7a2 2 0 0 1-2-2V6m3 0V4a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v2"/></svg></button></div></div><p v-if="event.location" class="mt-1 text-sm text-slate-500">{{ event.location }}</p><p v-if="event.description" class="mt-3 whitespace-pre-line text-sm text-slate-600">{{ event.description }}</p><span v-if="event.note" class="mt-3 inline-block rounded-full bg-amber-100 px-2 py-1 text-xs text-amber-800">Nota: {{ event.note.title }}</span></div></article></section><aside class="h-fit rounded-2xl border border-slate-200 bg-white p-5 shadow-sm"><h2 class="font-semibold text-slate-900">{{ editing ? 'Editar evento' : 'Novo evento' }}</h2><form @submit.prevent="save" class="mt-4 space-y-4"><input v-model="form.title" required placeholder="Título do evento" class="w-full rounded-xl border-slate-300 text-sm" /><input v-model="form.starts_at" required type="datetime-local" class="w-full rounded-xl border-slate-300 text-sm" /><input v-model="form.ends_at" type="datetime-local" class="w-full rounded-xl border-slate-300 text-sm" /><input v-model="form.location" placeholder="Local (opcional)" class="w-full rounded-xl border-slate-300 text-sm" /><textarea v-model="form.description" rows="3" placeholder="Descrição (opcional)" class="w-full rounded-xl border-slate-300 text-sm"></textarea><select v-model="form.note_id" class="w-full rounded-xl border-slate-300 text-sm"><option value="">Sem anotação vinculada</option><option v-for="note in notes" :key="note.id" :value="note.id">{{ note.title }}</option></select><div><label class="text-xs font-semibold text-slate-500">Cor do evento</label><input v-model="form.color" type="color" class="ml-3 h-8 w-12 rounded border-0 p-0" /></div><div class="flex justify-end gap-2 border-t border-slate-100 pt-4"><button v-if="editing" type="button" @click="reset" class="rounded-xl bg-slate-100 px-4 py-2.5 text-sm font-medium text-slate-700 hover:bg-slate-200">Cancelar</button><button type="submit" class="rounded-xl bg-slate-900 px-5 py-2.5 text-sm font-medium text-white">Salvar evento</button></div></form></aside></div></div></AuthenticatedLayout></template>
